function has_game_ended(board) {
	var pieces = this.get_pieces(board);
	if (pieces.length == 0) return false;

	if (pieces.length != 1) {
		return true;
	} else if (pieces.every(p => p.color == Color.RED) || pieces.every(p => p.color == Color.BLUE)) {
		return true;
	} else {
		return false;
	}
}

function has_game_ended(board) {
